import {stages,growthPerStage} from './evolution-shared.js';
const $=s=>document.querySelector(s),canvas=$('#game'),ctx=canvas.getContext('2d'),overlay=$('#overlay'),message=$('#message'),modeSelect=$('#mode'),codeInput=$('#code');
const keys=new Set(),pointers=new Map();let socket=null,playerId=null,state=null,room='',lastSend=0,lastLevel=-1,noticeTimer=0;
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
function randomCode(){const chars='ABCDEFGHJKLMNPQRSTUVWXYZ23456789',a=new Uint8Array(6);crypto.getRandomValues(a);return [...a].map(x=>chars[x%chars.length]).join('')}
function resetInput(){keys.clear();pointers.clear();document.querySelectorAll('.pressed').forEach(b=>b.classList.remove('pressed'))}
function connect(code,mode){code=code.trim().toUpperCase();if(!/^[A-Z0-9]{4,8}$/.test(code)){message.textContent='Enter a room code with 4–8 letters or numbers.';return}if(socket)socket.close();state=null;playerId=null;room=code;lastLevel=-1;message.textContent='Connecting…';const protocol=location.protocol==='https:'?'wss:':'ws:',ws=new WebSocket(`${protocol}//${location.host}/api/evolution/${code}?mode=${mode}`);socket=ws;ws.addEventListener('message',event=>{if(socket!==ws)return;let m;try{m=JSON.parse(event.data)}catch{return}if(m.type==='joined'){playerId=m.id;overlay.hidden=true;$('#room-label').textContent=`ROOM ${room} · share this code`;message.textContent='Connected!'}else if(m.type==='snapshot'){state=m;const me=m.players.find(p=>p.id===playerId);if(!me)return;$('#creature').textContent=`${stages[me.level]} · ${me.level+1}/50`;$('#mode-label').textContent=m.mode==='normal'?'Normal':'Friendly';$('#health').textContent=me.respawn>0?'Eaten! Returning…':me.protection>0?'Safe for a moment':'Explore & grow';$('#progress').textContent=me.level===49?'You reached T. rex!':`${me.xp%growthPerStage} / ${growthPerStage} food to next evolution`;$('#bar').style.width=me.level===49?'100%':`${(me.xp%growthPerStage)/growthPerStage*100}%`;if(lastLevel>=0&&me.level>lastLevel){const n=$('#notice');n.textContent=me.level===49?'🦖 You became a T. rex!':`✨ Evolved into ${stages[me.level]}!`;n.hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>n.hidden=true,2500)}lastLevel=me.level}});ws.addEventListener('error',()=>{if(socket===ws)message.textContent='Could not connect. Check the code and try again.'});ws.addEventListener('close',()=>{if(socket!==ws)return;socket=null;state=null;playerId=null;resetInput();overlay.hidden=false;message.textContent=`Disconnected from ${room}. Re-enter the code to join again.`;$('#room-label').textContent='Disconnected'})}
function input(){if(!socket||socket.readyState!==WebSocket.OPEN)return;const has=k=>keys.has(k)||[...pointers.values()].includes(k);socket.send(JSON.stringify({type:'input',dx:Number(has('right'))-Number(has('left')),dy:Number(has('down'))-Number(has('up'))}))}
function ellipse(x,y,rx,ry,color){ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}
function creature(p){const t=p.level/49,size=20+t*16;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.angle);if(p.respawn>0)ctx.globalAlpha=.2;else if(p.protection>0)ctx.globalAlpha=.65;ellipse(0,14,size*1.05,size*.58,'#315d3b33');ctx.lineWidth=6+t*6;ctx.lineCap='round';ctx.strokeStyle=p.color;ctx.beginPath();ctx.moveTo(-size*.4,0);ctx.quadraticCurveTo(-size*1.15,5,-size*1.6,Math.sin(performance.now()/300+p.slot)*5);ctx.stroke();for(const side of [-1,1]){ellipse(-size*.35,side*size*.65,size*.32,size*.2,'#385a4a');ellipse(size*.3,side*size*.62,size*.28,size*.2,'#385a4a')}ellipse(0,0,size,size*.67,'#344d40');ellipse(0,-2,size*.91,size*.59,p.color);ellipse(size*.62,0,size*.55,size*.55,'#344d40');ellipse(size*.63,-2,size*.49,size*.49,p.color);if(p.level>=9){ctx.fillStyle='#f7e4ac';ctx.beginPath();ctx.moveTo(-size*.4,-size*.44);ctx.lineTo(-size*.16,-size*(.9+t*.35));ctx.lineTo(size*.04,-size*.42);ctx.fill()}if(p.level>=19){ctx.fillStyle='#f6e7bb';for(const y of [-1,1]){ctx.beginPath();ctx.moveTo(size*.55,y*size*.33);ctx.lineTo(size*.5,y*size*.72);ctx.lineTo(size*.78,y*size*.3);ctx.fill()}}if(p.level>=29){ctx.fillStyle='#e3f5d5';for(let i=0;i<3;i++)ellipse(-size*.55+i*size*.29,-size*.12,3+t*2,3+t*2,'#e3f5d5')}ellipse(size*.78,-size*.2,3+t*1.5,4+t*1.5,'#263d37');ellipse(size*.81,-size*.23,1.2,1.5,'#fff');ctx.restore();ctx.textAlign='center';ctx.font='bold 13px system-ui';ctx.fillStyle='#315343';ctx.fillText(p.id===playerId?'YOU':`PLAYER ${p.slot}`,p.x,p.y-size-19);ctx.font='12px system-ui';ctx.fillText(`${stages[p.level]} · ${p.level+1}`,p.x,p.y-size-5)}
function render(now){const w=960,h=540;canvas.width=w;canvas.height=h;const me=state?.players.find(p=>p.id===playerId),cx=clamp((me?.x??900)-w/2,0,1800-w),cy=clamp((me?.y??550)-h/2,0,1100-h);ctx.fillStyle='#bfe4a9';ctx.fillRect(0,0,w,h);ctx.save();ctx.translate(-cx,-cy);for(let i=0;i<160;i++){const x=(i*137)%1800,y=(i*263)%1100;ellipse(x,y,13,7,i%2?'#acd89b':'#c8eab4');if(i%5===0){ellipse(x,y-3,3,3,'#fff3d7');ellipse(x+5,y-5,3,3,'#f6bcca')}}if(state){for(const f of state.food){ellipse(f.x,f.y+4,11,6,'#6ca26b44');ellipse(f.x,f.y,9,9,['#f9a786','#f6d36b','#9fcbe9'][f.kind]);ellipse(f.x-3,f.y-3,2,2,'#fff9df')}for(const p of state.players)creature(p)}ctx.restore();if(now-lastSend>80){input();lastSend=now}requestAnimationFrame(render)}
const keymap={w:'up',arrowup:'up',s:'down',arrowdown:'down',a:'left',arrowleft:'left',d:'right',arrowright:'right'};window.addEventListener('keydown',e=>{if(e.target instanceof HTMLInputElement||e.target instanceof HTMLSelectElement)return;const key=keymap[e.key.toLowerCase()];if(key){e.preventDefault();keys.add(key)}});window.addEventListener('keyup',e=>{const key=keymap[e.key.toLowerCase()];if(key)keys.delete(key)});window.addEventListener('blur',resetInput);document.addEventListener('visibilitychange',()=>{if(document.hidden)resetInput()});for(const button of document.querySelectorAll('[data-move]')){const action=button.dataset.move;button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);pointers.set(e.pointerId,action);button.classList.add('pressed')});const release=e=>{pointers.delete(e.pointerId);if(![...pointers.values()].includes(action))button.classList.remove('pressed')};for(const ev of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(ev,release)}$('#create').addEventListener('click',()=>connect(randomCode(),modeSelect.value));$('#join').addEventListener('click',()=>connect(codeInput.value,modeSelect.value));requestAnimationFrame(render);
